tokens.css:
--color-bg: #ffffff;
--color-surface: #f4f5f9;
--color-text: #141414;
--color-text-muted: #5c5853;
--color-border: #d8d4cf;
--color-primary: #001b76;
--color-on-primary: #ffffff;
--color-accent: #de7a40;
--color-on-accent: #001b76;
--font-display: "Familjen Grotesk", system-ui, sans-serif;
--font-body: "Hanken Grotesk", system-ui, sans-serif;
--text-sm: 14px;
--text-base: 18px;
--text-lg: 23px;
--text-xl: 28px;
--text-2xl: 35px;
--text-3xl: 44px;
--radius-control: 6px;
--radius-card: 12px;
--space-section: 104px;
--shadow-card: 0 1px 2px color-mix(in oklab, var(--color-text) 8%, transparent), 0 10px 30px color-mix(in oklab, var(--color-text) 12%, transparent);
